#include "knowledge.h"

const char *aic_knowledge_json(void)
{
    static const char kb[] =
    "{\"version\":\"1.0.0\",\"updated_at\":\"2026-11-24\",\"changelog\":[{\"version\":\"1.0.0\",\"date\":\"2026-11-24\",\"note\":\"首次随包分发：五组共 15 篇，每篇含正文、示意图节点、示例、要点卡片与来源记录。\"}],\"groups\":[{\"id\":\"memory\",\"title\":\"AI 记忆体系\",\"summary\":\"记忆条目从哪来、怎么被改、怎么被检索和遗忘。\",\"articles\":[{\"id\":\"memory-what\",\"title\":\"记忆条目是什么\",\"summary\":\"记忆不是聊天记录，而是从对话里抽出来的可复用结论。\",\"body\":[\"记忆条目（memory_entry）是从某一条消息里抽出的、以后还用得上的结论，它必须挂在一个来源消息上（source_message_id），因此任何一条记忆都能追溯到原话。\",\"抽取只认四类内容：稳定事实（你是谁、在做什么）、明确偏好（喜欢什么风格、不要什么）、约定（说好的规则、称呼、预算）、待办（还没做完的事）。寒暄、情绪化吐槽、一次性的临时信息不抽，抽了只会污染后面的检索。\",\"记忆不是越全越好。条目越长越难命中，也越占上下文预算；一条记忆应该能独立读懂，并且短到一句话说得清。\"],\"diagram\":[\"消息\",\"抽取四类\",\"记忆条目\",\"关键词索引\",\"检索注入\"],\"example\":\"用户说「以后回答别超过三句话，我不爱看长文」。这条会被抽成一条偏好记忆，下次组装上下文时命中，而不是每次都要用户重复。\",\"points\":[\"记忆必须可追溯到来源消息\",\"只抽事实/偏好/约定/待办四类\",\"一条记忆一句话说得清\"],\"sources\":[{\"title\":\"MemGPT: Towards LLMs as Operating Systems\",\"author\":\"Packer et al.\",\"url\":\"https://arxiv.org/abs/2310.08560\",\"license\":\"arXiv 非独占许可（仅引用）\",\"date\":\"2023-10-12\"}]},{\"id\":\"memory-edit-sync\",\"title\":\"改了 AI 的发言，记忆为什么要重建\",\"summary\":\"发言是记忆的来源，来源变了记忆必须整体重来。\",\"body\":[\"记忆条目的内容来自消息原文。一旦用户修改了 AI 的某条发言，旧记忆里可能还留着被删掉的错误说法，如果只做增量补充，就会出现「用户已经改过、AI 还在按旧说法回答」的矛盾。\",\"所以修改发言时，正确做法是在同一个事务里先按 source_message_id 物理删除该消息产生的全部记忆条目与关键词索引，再按新正文重新抽取写入。物理删除而不是软删除，是为了不留下能被检索命中的副本；事务保证要么全成要么全不成，不会出现「旧记忆删了、新记忆没写进去」的空窗。\",\"如果开了双端同步，还要发一条 memory_replace 事件，让对端做同样的重建，否则两端记忆会分叉。修改前的提示要写清楚「修改将同步更改 AI 记忆」，让用户知道影响范围。\"],\"diagram\":[\"改发言\",\"同事务\",\"删除旧记忆\",\"重新抽取\",\"写新索引\",\"广播事件\"],\"example\":\"AI 曾说「你对花生过敏」，用户改成「你对花生不过敏」。若不重建，记忆里仍有过敏条目，之后每次推荐食物都会误判。\",\"points\":[\"按来源消息物理删除，不留副本\",\"删除与重建必须同一事务\",\"跨端发 memory_replace 事件\"],\"sources\":[{\"title\":\"Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks\",\"author\":\"Lewis et al.\",\"url\":\"https://arxiv.org/abs/2005.11401\",\"license\":\"arXiv 非独占许可（仅引用）\",\"date\":\"2020-05-22\"}]},{\"id\":\"memory-lifecycle\",\"title\":\"记忆的生命周期\",\"summary\":\"抽取、索引、命中、注入、清理，五步各管一段。\",\"body\":[\"抽取发生在消息落库之后，重建发生在来源消息被修改之后，两者用同一套抽取规则，保证结果一致。索引是抽取时顺手写下的关键词，用于之后的模糊命中，不需要另建搜索引擎。\",\"命中发生在组装请求之前：把用户这句话里的关键词拿去查索引，命中的条目按相关度排序，取前若干条拼进上下文。注入要受预算约束，超出预算时宁可少放几条，也不要把一整段长文塞进去。"
    "\",\"清理有两类：一是来源消息被删除或被重写，记忆必须跟着走；二是长期未命中的条目可以按保留策略淘汰。淘汰只影响检索，不影响原来的聊天记录。\"],\"diagram\":[\"抽取\",\"索引\",\"命中\",\"注入预算\",\"清理\"],\"example\":\"三个月没被命中的节日偏好可以淘汰；但「称呼我叫小周」这种稳定事实应该保留，直到用户自己改口。\",\"points\":[\"抽取与重建用同一套规则\",\"注入受上下文预算约束\",\"淘汰只影响检索不影响记录\"],\"sources\":[{\"title\":\"Lost in the Middle: How Language Models Use Long Contexts\",\"author\":\"Liu et al.\",\"url\":\"https://arxiv.org/abs/2307.03172\",\"license\":\"arXiv 非独占许可（仅引用）\",\"date\":\"2023-07-06\"}]}]},{\"id\":\"prompt\",\"title\":\"提示词工程\",\"summary\":\"怎么写出稳定、可版本化、不互相打架的系统提示词。\",\"articles\":[{\"id\":\"prompt-structure\",\"title\":\"系统提示词的四段式\",\"summary\":\"角色、边界、风格、输出约定，缺一段就会飘。\",\"body\":[\"第一段写角色：你是谁、在什么场景下服务谁。角色要给具体身份，不要堆形容词，「一个说话直接的同事」比「一个极其专业、温暖、幽默、严谨的助手」有效得多。\",\"第二段写边界：什么不做、什么必须先问、什么必须拒绝。边界要用正向可执行的写法，「不确定时先复述你的理解再回答」比「不要胡说」更管用。第三段写风格：句子长短、称呼、要不要用列表。第四段写输出约定：格式、长度上限、必须包含的字段。\",\"四段之间不要重复。同一件事在边界和风格里各说一遍，模型会认为这是两个不同的要求，反而更容易跑偏。\"],\"diagram\":[\"角色\",\"边界\",\"风格\",\"输出约定\"],\"example\":\"角色：你是小周的技术同事。边界：不确定时先复述理解；不替小周做决定。风格：短句，不用感叹号。输出：最多五句，先给结论。\",\"points\":[\"角色给身份不给形容词\",\"边界写成可执行动作\",\"四段不重复同一要求\"],\"sources\":[{\"title\":\"Building effective agents\",\"author\":\"Anthropic\",\"url\":\"https://www.anthropic.com/engineering/building-effective-agents\",\"license\":\"公开技术文章（仅引用）\",\"date\":\"2024-12-19\"}]},{\"id\":\"prompt-version\",\"title\":\"提示词要版本化\",\"summary\":\"改坏了要能退回去，所以每次改动都是一条新版本。\",\"body\":[\"提示词是人设的核心资产，它的改动频率往往比代码高。把它存成版本序列（prompt_version），每次保存写一条新记录并把 current_version 指向它，历史版本不删除，才能做到「改坏了能退回去」。\",\"版本记录要带时间和内容全文，不要只存 diff。回滚不是把旧版本复制成新版本，而是把当前指针指回旧版本，这样历史仍然线性、可追溯。\",\"版本化的另一个好处是排错：用户说「昨天还很正常」，你可以直接对比昨天和今天用的两版提示词，而不是靠回忆。\"],\"diagram\":[\"编辑\",\"新版本\",\"指针切换\",\"旧版本保留\",\"可回滚\"],\"example\":\"v1 写了「幽默一点」，v2 改成「克制，不玩梗」。用户觉得 v2 太冷，回滚到 v1，v2 仍留在历史里。\",\"points\":[\"每次保存都是新版本\",\"存全文不存 diff\",\"回滚是指针回退不是覆盖\"],\"sources\":[{\"title\":\"OpenAI Cookbook: Techniques to improve reliability\",\"author\":\"OpenAI\",\"url\":\"https://github.com/openai/openai-cookbook\",\"license\":\"MIT\",\"date\":\"2024-01-01\"}]},{\"id\":\"prompt-anti-pattern\",\"title\":\"提示词的常见反模式\",\"summary\":\"堆形容词、互相冲突、只写否定、过度格式约束。\",\"body\":[\"堆形容词是最常见的浪费：「专业、温暖、幽默、严谨、耐心」同时出现时，模型只能取平均，结果是谁都不像。选一个主性格，其余交给具体行为描述。\",\"互相冲突"
    "的指令会让输出随机摇摆：「尽量简短」和「把每个细节都讲清楚」不能同时满足，模型每次挑一个，用户看到的就是不稳定。只写否定的指令同样低效：「不要用列表」不如「用连续段落」。\",\"过度格式约束（必须三段、每段不超过两行、必须带 emoji）会挤掉内容。格式只在真的有人按格式读的时候才值得写。\"],\"diagram\":[\"形容词堆叠\",\"指令冲突\",\"纯否定\",\"过度格式\"],\"example\":\"把「专业、温暖、幽默」换成「像同事说话，偶尔一句话调侃，但不影响结论」——同样三个词的意思，后者可执行。\",\"points\":[\"一个主性格，其余写行为\",\"不写互相冲突的要求\",\"否定句改成正面动作\"],\"sources\":[{\"title\":\"Prompt Engineering Guide\",\"author\":\"DAIR.AI\",\"url\":\"https://github.com/dair-ai/Prompt-Engineering-Guide\",\"license\":\"MIT\",\"date\":\"2024-06-01\"}]}]},{\"id\":\"context\",\"title\":\"上下文管理\",\"summary\":\"模型一次能看多少、该放什么、放不下怎么取舍。\",\"articles\":[{\"id\":\"context-window\",\"title\":\"上下文窗口与消息裁剪\",\"summary\":\"窗口是硬上限，裁剪策略决定长对话还能不能用。\",\"body\":[\"上下文窗口是模型单次能接收的 token 上限。聊天越长，越不可能把所有历史都放进去，必须裁剪。最朴素也最有效的策略是保留最近 N 条消息，再补一条摘要说明更早发生了什么。\",\"裁剪要尊重消息语义：被撤回的消息、被重新生成替换掉的旧回复，都不应该进上下文，否则模型会同时看到两个互相矛盾的版本。配对关系（用户问题 + 它的回答）也要成对保留，只留回答会让模型失去提问语境。\",\"裁剪之后上下文变短，长对话的连贯性会下降，这是必然代价。用摘要代替丢弃，比直接扔掉更划算。\"],\"diagram\":[\"全部历史\",\"排除撤回/替换\",\"保留最近 N 条\",\"补摘要\",\"送入模型\"],\"example\":\"第 300 轮时只带最近 40 条 + 一句「此前你们聊过搬家和工作变动」，比强塞 300 条更省也更有用。\",\"points\":[\"硬上限不可绕\",\"撤回与替换的消息不进上下文\",\"问答成对保留\"],\"sources\":[{\"title\":\"Lost in the Middle: How Language Models Use Long Contexts\",\"author\":\"Liu et al.\",\"url\":\"https://arxiv.org/abs/2307.03172\",\"license\":\"arXiv 非独占许可（仅引用）\",\"date\":\"2023-07-06\"}]},{\"id\":\"context-budget\",\"title\":\"token 预算怎么分\",\"summary\":\"系统提示、历史、注入区、输出预留，四份要提前分好。\",\"body\":[\"把窗口当成一笔预算，先扣掉必须在的部分：系统提示词（人设与规则）、输出预留（模型要生成的内容）。剩下的才是历史与注入区可以争的。\",\"输出预留最容易被忽略：如果输入塞到窗口九成，模型只剩一成空间回答，回答会被硬截断。经验上至少留出四分之一给输出，长回答场景要留得更多。\",\"注入区（插件片段、知识库引用）和历史争预算时，按「这次问题需要什么」分配，而不是按谁先来。注入内容要标来源、可截断，超预算时先截注入、再砍最早的历史。\"],\"diagram\":[\"窗口\",\"系统提示\",\"输出预留\",\"历史\",\"注入区\"],\"example\":\"窗口 64k：系统提示 2k、输出预留 16k，剩余 46k 给历史与注入。注入片段超过 4k 就截断，并标注「已截断」。\",\"points\":[\"先扣系统提示与输出预留\",\"输出至少留四分之一\",\"超预算先截注入再砍历史\"],\"sources\":[{\"title\":\"DeepSeek API 文档：模型与上下文长度\",\"author\":\"DeepSeek\",\"url\":\"https://api-docs.deepseek.com\",\"license\":\"公开文档（仅引用）\",\"date\":\"2025-01-01\"}]},{\"id\":\"context-injection\",\"title\":\"插件与知识库共用注入区\",\"summary\":\"一个注入区、一份预算、每条都标来源。\",\"body\":[\"插件输出与知识库引用本质是同一类东西：外部材料，临时塞进上下文。它们应该共用一个注入区、一份预算，否则各算各的，"
    "加起来就超了。\",\"每条注入都要标来源：来自哪个插件、哪篇知识库文章、第几段。标来源有两个作用：模型知道该不该信，用户知道这段话从哪来。\",\"注入内容不携带全文。知识库动辄几千字，把整篇塞进去既挤掉历史，又稀释重点；只带被选中的那一段，再加一行来源标注，信息密度最高。\"],\"diagram\":[\"插件输出\",\"知识引用\",\"共用注入区\",\"标来源\",\"裁剪到预算\"],\"example\":\"选中「token 预算怎么分」的第二段，注入的是那 90 个字加一行来源，而不是整篇 600 字。\",\"points\":[\"插件与知识库共用一份预算\",\"每条注入标来源\",\"只带选中片段不带全文\"],\"sources\":[{\"title\":\"Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks\",\"author\":\"Lewis et al.\",\"url\":\"https://arxiv.org/abs/2005.11401\",\"license\":\"arXiv 非独占许可（仅引用）\",\"date\":\"2020-05-22\"}]}]},{\"id\":\"longchat\",\"title\":\"长对话管理\",\"summary\":\"对话变长之后会怎么坏，以及怎么续命。\",\"articles\":[{\"id\":\"longchat-degrade\",\"title\":\"长对话为什么会变笨\",\"summary\":\"中间的信息会被忽略，越长的上下文越不可靠。\",\"body\":[\"模型对上下文不同位置的利用并不均匀：开头和结尾的利用率高，中间容易漏。这个现象叫「中间遗忘」，它意味着把关键信息塞进第 50 条消息里，比塞在第一条更容易被忽略。\",\"另一个问题是干扰：上下文里相似的、过时的、被推翻的说法越多，模型越容易抓住旧版本回答。这就是为什么撤回与替换的消息必须从上下文里排除干净。\",\"所以「上下文更长」不等于「更聪明」。在长对话里，准确率往往随长度下降，直到你换一种组织方式。\"],\"diagram\":[\"强利用\",\"中间薄弱\",\"强利用\"],\"example\":\"第 3 条说预算 5000，第 80 条说预算改成 8000。若两条都在上下文里，模型有一半概率按 5000 回答。\",\"points\":[\"中间位置最容易被忽略\",\"过时说法会互相干扰\",\"更长不等于更准\"],\"sources\":[{\"title\":\"Lost in the Middle: How Language Models Use Long Contexts\",\"author\":\"Liu et al.\",\"url\":\"https://arxiv.org/abs/2307.03172\",\"license\":\"arXiv 非独占许可（仅引用）\",\"date\":\"2023-07-06\"}]},{\"id\":\"longchat-summarize\",\"title\":\"摘要与话题切分\",\"summary\":\"该总结时总结，该新开就新开。\",\"body\":[\"话题变了就新开会话，是最省钱也最有效的长对话管理。用户从「改简历」聊到「装修预算」，两者共享上下文只会互相干扰。判断依据是：新问题是否还需要旧对话的细节。\",\"同一话题但太长时，做摘要：把更早的对话压成几句结论（决定了什么、排除了什么、还差什么），放在上下文最前面。摘要要写结论和约束，不写过程。\",\"摘要本身也有成本，不必每轮都做。按消息条数或 token 占比触发（比如历史超过预算的六成），触发时一次性压缩到一成左右。\"],\"diagram\":[\"话题变化\",\"新开会话\",\"过长\",\"摘要结论\",\"放最前\"],\"example\":\"把「改简历」前 60 轮压成：目标岗位是后端、已排除外包、简历只差项目量化数据。之后每轮都带着这三句。\",\"points\":[\"话题变就新开\",\"摘要写结论不写过程\",\"按预算占比触发压缩\"],\"sources\":[{\"title\":\"MemGPT: Towards LLMs as Operating Systems\",\"author\":\"Packer et al.\",\"url\":\"https://arxiv.org/abs/2310.08560\",\"license\":\"arXiv 非独占许可（仅引用）\",\"date\":\"2023-10-12\"}]},{\"id\":\"longchat-retrieval\",\"title\":\"按需检索代替全量堆叠\",\"summary\":\"需要哪段拿哪段，不要把整本历史都带上。\",\"body\":[\"长对话里真正被用到的历史往往只有几条。与其把 300 条消息都塞进上下文，不如在组装请求时按当前问题检索相关片段，只带命中的部分。\","
    "\"检索的实现可以很轻：关键词索引 + 相关度排序，不需要向量库。中文按两字词切分、英文按单词切分，去掉停用词之后建索引，已经能覆盖大部分「我刚才说的那个」场景。\",\"检索也会漏。所以策略是「检索 + 最近若干条」并存：近处靠窗口保证连贯，远处靠检索保证回忆。两者互补，比单一策略稳。\"],\"diagram\":[\"当前问题\",\"关键词检索\",\"命中片段\",\"近若干条\",\"合并注入\"],\"example\":\"用户问「上次说的那个部署脚本放哪了」，检索命中第 12 轮的文件路径，直接带进上下文，不用全量历史。\",\"points\":[\"关键词索引够用，不必上向量库\",\"检索与最近窗口并存\",\"命中片段要标出处\"],\"sources\":[{\"title\":\"Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks\",\"author\":\"Lewis et al.\",\"url\":\"https://arxiv.org/abs/2005.11401\",\"license\":\"arXiv 非独占许可（仅引用）\",\"date\":\"2020-05-22\"}]}]},{\"id\":\"token\",\"title\":\"token 知识\",\"summary\":\"模型按 token 计数、按 token 计费，先搞清楚它是什么。\",\"articles\":[{\"id\":\"token-what\",\"title\":\"token 是什么\",\"summary\":\"模型看到的不是字，是切好的片段。\",\"body\":[\"模型不直接处理字符，而是把文本切成 token 再映射成数字。切分规则由分词器（tokenizer）决定，常见做法是字节对编码（BPE）：从字符开始，反复合并出现频率最高的相邻对。\",\"因为按字节切，一个汉字通常占 2-3 个 token，一个英文单词常见是 1 个 token，生僻词会被切成多个。这解释了为什么同样长度的中英文，消耗的 token 差别很大。\",\"token 是计费和限流的单位。上下文窗口、每分钟请求数、价格表，全部以 token 计。写提示词时省 token，等于省钱也等于给回答留空间。\"],\"diagram\":[\"文本\",\"分词器\",\"token 序列\",\"模型\"],\"example\":\"「你好，世界」在多数分词器里是 4-6 个 token；「hello world」是 2 个 token。同样的意思，中文更贵。\",\"points\":[\"按字节切，汉字常占 2-3 token\",\"生僻词会被切碎\",\"token 是计费与限流单位\"],\"sources\":[{\"title\":\"Neural Machine Translation of Rare Words with Subword Units\",\"author\":\"Sennrich et al.\",\"url\":\"https://arxiv.org/abs/1508.07909\",\"license\":\"arXiv 非独占许可（仅引用）\",\"date\":\"2015-08-31\"}]},{\"id\":\"token-count\",\"title\":\"怎么算 token 用量\",\"summary\":\"本地估算与服务端用量对不上时，以服务端为准。\",\"body\":[\"本地估算只能靠近似公式：中文按字数、英文按字节数除以 4。它能用于界面提示和预算控制，但和真实计费会有偏差，尤其是代码、符号、混合语言。\",\"真实用量来自服务端返回的 usage 字段（prompt_tokens / completion_tokens）。只要接口给了这个字段，就应该以它为准记账，本地估算只做兜底。\",\"估算与真实的差值本身是有用的信号：如果长期偏差很大，说明提示词里有大量被切碎的符号，值得优化格式。\"],\"diagram\":[\"本地估算\",\"实际请求\",\"服务端 usage\",\"入账\",\"偏差观察\"],\"example\":\"本地估算 1200 token，服务端报 1480。差异来自 JSON 片段里的引号与括号被逐字符切分。\",\"points\":[\"估算只做兜底\",\"以服务端 usage 入账\",\"偏差大说明格式可优化\"],\"sources\":[{\"title\":\"DeepSeek API 文档：用量与计费\",\"author\":\"DeepSeek\",\"url\":\"https://api-docs.deepseek.com\",\"license\":\"公开文档（仅引用）\",\"date\":\"2025-01-01\"}]},{\"id\":\"token-cost\",\"title\":\"费用结构与省钱策略\",\"summary\":\"输入比输出便宜，重复上下文最贵。\",\"bod"
    "y\":[\"价格表通常把输入和输出分开计价，输出单价更高，因为生成比读取更耗算力。省钱的第一原则是别让模型生成不需要的内容：限定长度、要求先给结论。\",\"第二原则是别重复发送同样的上下文。很多请求里系统提示词一模一样，如果服务端支持上下文缓存，命中缓存的部分会便宜很多；即便不支持，缩短系统提示也是直接省钱。\",\"第三原则是选对模型：简单任务用便宜的小模型，复杂推理再切大模型。会话级保存模型选择，比全局设置更贴近真实使用。\"],\"diagram\":[\"输入计价\",\"输出更贵\",\"缓存命中\",\"选对模型\"],\"example\":\"同一段 2000 token 的系统提示，一天发 100 次，就是 20 万 token 的重复输入；压到 800 token，直接省六成。\",\"points\":[\"输出比输入贵，先控长度\",\"重复上下文是最大浪费\",\"按任务难度选模型\"],\"sources\":[{\"title\":\"DeepSeek API 文档：模型与价格\",\"author\":\"DeepSeek\",\"url\":\"https://api-docs.deepseek.com/quick_start/pricing\",\"license\":\"公开文档（仅引用）\",\"date\":\"2025-01-01\"}]}]}]}";
    return kb;
}

